def load_npz_weights(path):
    with np.load(path, allow_pickle=False) as data:
        flat_dict = {k: v for k, v in data.items()}
    params_flat = {k.replace('params/', ''): v for k, v in flat_dict.items() if k.startswith('params/')}
    stats_flat = {k.replace('stats/', ''): v for k, v in flat_dict.items() if k.startswith('stats/')}
    return {
        'params': unflatten_dict({tuple(k.split('/')): v for k, v in params_flat.items()}),
        'batch_stats': unflatten_dict({tuple(k.split('/')): v for k, v in stats_flat.items()})
    }

def load_ensemble_weights(paths):
    ensemble_vars = []
    if ENSEMBLE_MODE == 'single':
        paths = [paths[0]]
    for p in paths:
        if Path(p).exists():
            print(f"📦 Loading weights: {p}")
            ensemble_vars.append(load_npz_weights(p))
        else:
            print(f"⚠️ Warning: Path not found {p}")
    return ensemble_vars
