class Pix2PixGenerator(nn.Module):
    @nn.compact
    def __call__(self, x, train: bool = False):
        def conv_bn_leaky(feat, out_c):
            feat = nn.Conv(out_c, (4, 4), strides=(2, 2), padding='SAME')(feat)
            feat = nn.BatchNorm(use_running_average=not train)(feat)
            return nn.leaky_relu(feat, 0.2)

        s1 = nn.leaky_relu(nn.Conv(64, (4, 4), strides=(2, 2), padding='SAME')(x), 0.2)
        s2 = conv_bn_leaky(s1, 128)
        s3 = conv_bn_leaky(s2, 256)

        def up_bn_relu(feat, skip, out_c):
            feat = nn.ConvTranspose(out_c, (4, 4), strides=(2, 2), padding='SAME')(feat)
            feat = nn.BatchNorm(use_running_average=not train)(feat)
            feat = nn.relu(feat)
            return jnp.concatenate([feat, skip], axis=-1)

        u1 = up_bn_relu(s3, s2, 128)
        u2 = up_bn_relu(u1, s1, 64)
        return nn.ConvTranspose(1, (4, 4), strides=(2, 2), padding='SAME')(u2)

